pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best-Fit principle).
    // Lower residual is generally better.
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" that cannot fit common items.
    // If post_residual is small but not zero, it's often worse than having 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Heuristic: If we are near the end of the stream, prioritize filling bins tightly.
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.5;
    }

    // Lookahead logic: If the next item fits into the current post_residual,
    // incentivize choosing this bin to avoid opening a new one later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // New bin logic: Penalize opening a new bin heavily unless the current bin
    // is a very poor fit for the current item.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is low or the item is large
        // and would create a very awkward residual in existing bins.
        score += 30.0;
        score -= (open_bins_count as f64 * 0.5);
    }

    // Adjust score based on how the current bin compares to the average residual.
    // If this bin is "emptier" than average, we prefer to fill it more.
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    }

    // If this is the last chance to fit the item in an existing bin,
    // provide a slight incentive to take it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // Penalize empty bins (high post_residual) exponentially more as the stream progresses.
    let mut score = post_res + (post_res * post_res / bin_capacity as f64) * (1.0 + progress);

    // Penalty for creating a bin that is too small for the next item.
    // If the next item won't fit, we penalize the current placement more heavily.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Heuristic: If this is a new bin (bin_residual == bin_capacity),
    // apply a dynamic cost that makes it less attractive unless existing bins
    // are very inefficient (high mean_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening new bins; reduced by mean_residual of existing bins.
        // As the stream progresses, the penalty for a new bin decreases slightly 
        // to avoid "bottlenecking" at the very end.
        score += (bin_capacity as f64 * 0.8) - (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // Reward placements that balance the residual across bins to keep options open.
        // We subtract a factor proportional to how much this bin deviates from the mean.
        let deviation = (post_res - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // Adjust for the scarcity of options: if this is the last fitting bin, 
    // prioritize using it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A bin is a "new bin" if bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual: Best-Fit logic suggests prioritizing smaller post_residuals.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely.
    if is_new_bin {
        // Only open a new bin if we are forced to (no other bins fit) or if the state is very early.
        // If fitting_bins_count > 0, we heavily penalize opening a new bin.
        if fitting_bins_count > 0 {
            score += 150.0 + (1.0 - progress) * 50.0;
        } else {
            score = 0.0; // Accept the necessity of a new bin.
        }
    } else {
        // Heuristic for existing bins:
        // 1. Reward bins that leave space for the lookahead item (next_item_size).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // 2. Penalize creating "dead zones" (very small residuals that are unlikely to fit future items).
        // If post_residual is < 10, it's likely a dead zone since min item size is 1.
        if post_residual > 0 && post_residual < 10 {
            score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
        }

        // 3. Global state awareness: If we have many open bins, prioritize filling them tightly.
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 2.0;
        }

        // 4. Balance the fill level relative to the mean residual of all open bins.
        // This encourages "leveling" the bins to prevent one bin from becoming an outlier.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero (fragmentation).
    // If post_residual is small (1-9), it often prevents future larger items from fitting.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. New Bin Threshold: Discourage opening a new bin unless the current fit is extremely poor.
    // If we are forced to open a new bin, bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the existing options are very poor (high post_residual).
            score += 60.0; 
        } else {
            score -= 10.0;
        }
    }

    // 4. Harmonic Density: Favor bins that align with common item size distributions.
    // Using modulo to favor "clean" remaining capacities.
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.5;

    // 5. Global Pressure: As we approach the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    score
}

